-- ============================================================
-- Stage 3 patch for regulation_id = 27880
-- Updates stage3_json and analysis_json with control designs.
-- Run inside a transaction; verify row counts before COMMIT.
-- ============================================================

BEGIN TRANSACTION;

-- REQ-001: Risk Assessment
UPDATE compliance_analysis
SET    stage3_json   = N'{"requirement_id": "REQ-001", "requirement_title": "Risk Assessment", "obligations": [{"obligation_id": "REQ-001-OB-001", "obligation_text": "Identify, assess, and document money laundering risks and keep the assessment up to date, taking into account a wide range of risk factors, including those relating to customers, countries or geographic areas, products, services, transactions and delivery channels.", "execution_category": "Ongoing_Control", "control": {"control_title": "Enterprise-Wide AML/CFT Risk Assessment Review", "control_objective": "Ensure the institution''s AML/CFT risk assessment remains current and covers all prescribed risk factor categories on a continuous basis.", "control_description": "The Compliance function maintains a formal enterprise-wide AML/CFT risk assessment document that is reviewed and updated at least annually, and on an ad-hoc basis following material changes in business activities, regulatory guidance, or the external threat environment. The assessment is structured to evaluate risk across all prescribed dimensions: customers, geographies, products, services, transactions, and delivery channels. Results are presented to senior management for approval and retained as documented evidence.", "control_owner": "Compliance / Risk Management", "control_type": "Detective", "execution_type": "Hybrid", "frequency": "Annual (plus event-driven updates)", "control_level": "Process", "evidence_generated": "Signed and dated AML/CFT Risk Assessment Report with version history and senior management approval record", "key_steps": ["Compliance schedules and initiates the annual risk assessment review cycle, distributing a structured template to all business units.", "Business units submit risk data covering customer segments, product portfolios, geographic exposures, transaction types, and delivery channels.", "Compliance consolidates submissions, scores inherent and residual risk, and documents the rationale for each risk rating.", "Draft assessment is reviewed and challenged by senior management or the AML Committee; findings are incorporated.", "Final report is approved, signed, version-controlled, and stored in the designated compliance repository."], "residual_risk_if_failed": "High"}}, {"obligation_id": "REQ-001-OB-002", "obligation_text": "Assess, prior to their use, the risks associated with new products, business practices and technologies.", "execution_category": "One_Time_Implementation", "control": null}, {"obligation_id": "REQ-001-OB-003", "obligation_text": "Provide risk assessment reports to the supervisory authorities upon request.", "execution_category": "One_Time_Implementation", "control": null}]}',
       analysis_json = N'{"requirement_id": "REQ-001", "requirement_title": "Risk Assessment", "obligations": [{"obligation_id": "REQ-001-OB-001", "obligation_text": "Identify, assess, and document money laundering risks and keep the assessment up to date, taking into account a wide range of risk factors, including those relating to customers, countries or geographic areas, products, services, transactions and delivery channels.", "obligation_type": "Detective", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["Policy", "Report", "Record"], "test_method": "Auditor reviews the enterprise-wide AML risk assessment document, checks the date of last update, and verifies it covers all required risk factor categories.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 5"}, {"obligation_id": "REQ-001-OB-002", "obligation_text": "Assess, prior to their use, the risks associated with new products, business practices and technologies.", "obligation_type": "Detective", "criticality": "High", "execution_category": "One_Time_Implementation", "evidence_expected": ["Policy", "Approval", "Report"], "test_method": "Auditor selects a sample of new products or services launched in the review period and confirms a documented AML risk assessment was completed and approved before go-live.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 5"}, {"obligation_id": "REQ-001-OB-003", "obligation_text": "Provide risk assessment reports to the supervisory authorities upon request.", "obligation_type": "Reporting", "criticality": "Medium", "execution_category": "One_Time_Implementation", "evidence_expected": ["Report", "Record"], "test_method": "Auditor confirms a designated repository exists for finalized risk assessment reports and that a procedure for responding to supervisory requests is documented and tested.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 5"}], "controls": [{"control_title": "Enterprise-Wide AML/CFT Risk Assessment Review", "control_objective": "Ensure the institution''s AML/CFT risk assessment remains current and covers all prescribed risk factor categories on a continuous basis.", "control_description": "The Compliance function maintains a formal enterprise-wide AML/CFT risk assessment document that is reviewed and updated at least annually, and on an ad-hoc basis following material changes in business activities, regulatory guidance, or the external threat environment. The assessment is structured to evaluate risk across all prescribed dimensions: customers, geographies, products, services, transactions, and delivery channels. Results are presented to senior management for approval and retained as documented evidence.", "control_owner": "Compliance / Risk Management", "control_type": "Detective", "execution_type": "Hybrid", "frequency": "Annual (plus event-driven updates)", "control_level": "Process", "evidence_generated": "Signed and dated AML/CFT Risk Assessment Report with version history and senior management approval record", "key_steps": ["Compliance schedules and initiates the annual risk assessment review cycle, distributing a structured template to all business units.", "Business units submit risk data covering customer segments, product portfolios, geographic exposures, transaction types, and delivery channels.", "Compliance consolidates submissions, scores inherent and residual risk, and documents the rationale for each risk rating.", "Draft assessment is reviewed and challenged by senior management or the AML Committee; findings are incorporated.", "Final report is approved, signed, version-controlled, and stored in the designated compliance repository."], "residual_risk_if_failed": "High"}]}'
WHERE  regulation_id  = 27880
  AND  requirement_id = 'REQ-001'
  AND  schema_version = 'v2'
  AND  is_current     = 1;

-- REQ-002: Customer Due Diligence
UPDATE compliance_analysis
SET    stage3_json   = N'{"requirement_id": "REQ-002", "requirement_title": "Customer Due Diligence", "obligations": [{"obligation_id": "REQ-002-OB-001", "obligation_text": "Shall not keep or open anonymous accounts or accounts in obviously fictitious names, or numbered accounts.", "execution_category": "Ongoing_Control", "control": {"control_title": "Anonymous and Fictitious Account Prevention", "control_objective": "Prevent the opening or maintenance of any account that lacks verified customer identity.", "control_description": "The core banking system enforces mandatory identity verification fields that cannot be bypassed during account creation; any attempt to open an account without a verified name linked to an official identity document is blocked at the system level. Existing accounts are subject to periodic batch reviews to detect anomalies such as placeholder names, number-only identifiers, or missing identity linkages. Exceptions are escalated to Compliance for investigation and remediation.", "control_owner": "Retail / Corporate Banking Operations", "control_type": "Preventive", "execution_type": "Automated", "frequency": "Per-Transaction (account opening) + Periodic batch review", "control_level": "System", "evidence_generated": "System rejection logs for incomplete onboarding attempts; periodic account name validation report", "key_steps": ["Core banking system validates that a verified customer name and linked national ID or passport number are present before an account record can be saved.", "Any submission missing mandatory identity fields triggers a hard system block with an error code logged.", "A monthly batch job scans existing account records for null, numeric-only, or flagged placeholder name fields.", "Anomalies identified in the batch scan are routed to Compliance for review within five business days.", "Compliance documents the outcome of each review and escalates confirmed violations to senior management."], "residual_risk_if_failed": "High"}}, {"obligation_id": "REQ-002-OB-002", "obligation_text": "Apply due diligence measures to customers. The Implementing Regulation shall set forth the instances and types of measures.", "execution_category": "Ongoing_Control", "control": {"control_title": "Customer Due Diligence Completion at Onboarding", "control_objective": "Ensure every customer relationship is subject to completed CDD before or at the point of onboarding.", "control_description": "The onboarding workflow requires all mandatory CDD tasks to be marked complete in the customer management system before an account can be activated. A compliance checklist aligned with the Implementing Regulation is embedded in the workflow and signed off by the relationship manager and a compliance reviewer. Incomplete CDD cases trigger an automated hold on account activation.", "control_owner": "Compliance / All Business Units", "control_type": "Preventive", "execution_type": "Hybrid", "frequency": "Per-Transaction (each new customer onboarding)", "control_level": "Process", "evidence_generated": "Completed CDD checklist in the customer file; account activation audit trail showing CDD sign-off date", "key_steps": ["Relationship manager initiates onboarding and is presented with a mandatory CDD checklist generated from the current Implementing Regulation requirements.", "Required documentation (identity, address, purpose of relationship, source of funds) is collected and uploaded to the customer file.", "Compliance reviewer verifies completeness and quality of CDD documentation and marks the checklist as approved.", "System allows account activation only after all checklist items show a completed status.", "Completed customer file is retained in the document management system for the required retention period."], "residual_risk_if_failed": "High"}}, {"obligation_id": "REQ-002-OB-003", "obligation_text": "Determine the extent of due diligence measures based on the risks related to a customer or business relationship.", "execution_category": "Ongoing_Control", "control": {"control_title": "Risk-Based Customer Risk Rating and CDD Tier Assignment", "control_objective": "Ensure the level of CDD applied to each customer is proportionate to their assessed risk rating.", "control_description": "A documented customer risk rating methodology scores customers across defined risk criteria (customer type, geography, product, transaction behavior) and automatically assigns a risk tier — Low, Medium, or High. Each tier maps to a defined CDD level: Simplified, Standard, or Enhanced. The risk rating is reviewed at onboarding, at defined periodic intervals, and on a trigger basis when material changes occur in the customer relationship.", "control_owner": "Compliance", "control_type": "Detective", "execution_type": "Hybrid", "frequency": "Per-Transaction (onboarding) + Annual periodic review + Event-Driven", "control_level": "Process", "evidence_generated": "Customer risk rating record with scoring rationale; CDD tier assignment log in the customer management system", "key_steps": ["At onboarding, the system calculates an initial risk score based on structured customer profile data using the approved scoring methodology.", "The risk score maps to a CDD tier (Simplified / Standard / Enhanced) and the corresponding due diligence tasks are auto-populated in the workflow.", "Relationship managers complete the assigned CDD tasks; Compliance reviews and approves the rating for Medium and High-risk customers.", "Risk ratings are re-evaluated annually in batch and on a trigger basis (e.g., adverse media, sanctions alert, unusual transaction pattern).", "Changes to risk ratings are documented with the reason for change and approved by the appropriate authority level."], "residual_risk_if_failed": "High"}}, {"obligation_id": "REQ-002-OB-004", "obligation_text": "Where a higher risk of money laundering was identified, apply enhanced due diligence measures.", "execution_category": "Ongoing_Control", "control": {"control_title": "Enhanced Due Diligence for High-Risk Customers", "control_objective": "Ensure all customers classified as high-risk are subject to documented EDD procedures including senior management approval.", "control_description": "When a customer receives a High risk rating, the system automatically triggers an EDD workflow requiring additional information collection (e.g., senior management approval, enhanced source of funds verification, more frequent periodic reviews). EDD cannot be bypassed; the account remains restricted until all EDD steps are completed and approved by an authorized compliance officer at the required seniority level.", "control_owner": "Compliance / Financial Intelligence Unit", "control_type": "Preventive", "execution_type": "Hybrid", "frequency": "Event-Driven (on High-risk rating) + Enhanced periodic review cycle", "control_level": "Process", "evidence_generated": "EDD checklist with completed fields; senior management approval record; enhanced periodic review reports", "key_steps": ["System detects High risk rating and automatically activates the EDD workflow, restricting full account access until completion.", "Relationship manager collects enhanced documentation: source of wealth, source of funds, detailed business purpose, UBO chain.", "Compliance officer at the required seniority level reviews the EDD package and either approves, requests further information, or escalates.", "Approved EDD is documented in the customer file with the approver''s identity and date.", "High-risk customers are scheduled for enhanced periodic review at a more frequent interval than standard customers (e.g., every 6 months vs. annually)."], "residual_risk_if_failed": "High"}}, {"obligation_id": "REQ-002-OB-005", "obligation_text": "Use appropriate systems to determine whether a customer or beneficial owner is or has become a politically exposed person (PEP) and if so, apply additional measures as prescribed by the Implementing Regulation.", "execution_category": "Ongoing_Control", "control": {"control_title": "PEP Screening and Additional Measures Workflow", "control_objective": "Ensure all customers and beneficial owners are screened against PEP databases at onboarding and on an ongoing basis, with additional measures applied upon a confirmed match.", "control_description": "The compliance screening system performs automated PEP screening for all customers and beneficial owners at onboarding and on a continuous or periodic basis thereafter using a licensed third-party database covering domestic and foreign PEPs and senior officials of international organizations. Positive matches generate alerts routed to the Financial Intelligence Unit for review. Confirmed PEP status triggers a mandatory additional measures workflow aligned with the Implementing Regulation.", "control_owner": "Compliance / Financial Intelligence Unit", "control_type": "Detective", "execution_type": "Automated", "frequency": "Per-Transaction (onboarding) + Ongoing/Daily batch rescreening", "control_level": "System", "evidence_generated": "Screening system alert log; PEP match review and disposition records; additional measures completion records in the customer file", "key_steps": ["Screening system automatically runs PEP checks on all customers and beneficial owners at onboarding using integrated third-party PEP database.", "Daily batch rescreening runs against the full customer base to catch newly designated PEPs or changes in PEP status.", "Generated alerts are routed to the FIU queue with a defined SLA for initial review (e.g., within 2 business days).", "FIU analyst reviews the alert, confirms or dismisses the match, and documents the rationale.", "Confirmed PEP matches trigger the mandatory additional measures workflow: senior management approval, enhanced source of wealth verification, and more frequent periodic reviews, all documented in the customer file."], "residual_risk_if_failed": "High"}}]}',
       analysis_json = N'{"requirement_id": "REQ-002", "requirement_title": "Customer Due Diligence", "obligations": [{"obligation_id": "REQ-002-OB-001", "obligation_text": "Shall not keep or open anonymous accounts or accounts in obviously fictitious names, or numbered accounts.", "obligation_type": "Preventive", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["System Configuration", "Log", "Procedure"], "test_method": "Auditor attempts to open a test account without valid identity documents in a sandboxed environment and confirms the system blocks the action; also reviews a sample of existing accounts for compliance.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 6"}, {"obligation_id": "REQ-002-OB-002", "obligation_text": "Apply due diligence measures to customers. The Implementing Regulation shall set forth the instances and types of measures.", "obligation_type": "Governance", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["Policy", "Procedure", "Record"], "test_method": "Auditor reviews the CDD policy and selects a sample of onboarded customers to confirm CDD was completed at onboarding in accordance with the Implementing Regulation.", "clarity_score": 4, "needs_manual_review": false, "source_reference": "Article 7(1)"}, {"obligation_id": "REQ-002-OB-003", "obligation_text": "Determine the extent of due diligence measures based on the risks related to a customer or business relationship.", "obligation_type": "Governance", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["Policy", "Record", "Procedure"], "test_method": "Auditor reviews the customer risk rating methodology and confirms it maps risk levels to CDD tiers (Simplified / Standard / Enhanced); validates a sample of customer risk ratings against applied CDD level.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 7(2)"}, {"obligation_id": "REQ-002-OB-004", "obligation_text": "Where a higher risk of money laundering was identified, apply enhanced due diligence measures.", "obligation_type": "Governance", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["Policy", "Procedure", "Approval", "Record"], "test_method": "Auditor selects a sample of customers rated high-risk and confirms EDD procedures were applied, documented, and escalated for approval in accordance with policy.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 7(2)"}, {"obligation_id": "REQ-002-OB-005", "obligation_text": "Use appropriate systems to determine whether a customer or beneficial owner is or has become a politically exposed person (PEP) and if so, apply additional measures as prescribed by the Implementing Regulation.", "obligation_type": "Governance", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["System Configuration", "Log", "Procedure", "Record"], "test_method": "Auditor confirms screening system is configured for PEP databases; reviews a sample of PEP alerts to verify timely review and application of additional measures.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 8"}], "controls": [{"control_title": "Anonymous and Fictitious Account Prevention", "control_objective": "Prevent the opening or maintenance of any account that lacks verified customer identity.", "control_description": "The core banking system enforces mandatory identity verification fields that cannot be bypassed during account creation; any attempt to open an account without a verified name linked to an official identity document is blocked at the system level. Existing accounts are subject to periodic batch reviews to detect anomalies such as placeholder names, number-only identifiers, or missing identity linkages. Exceptions are escalated to Compliance for investigation and remediation.", "control_owner": "Retail / Corporate Banking Operations", "control_type": "Preventive", "execution_type": "Automated", "frequency": "Per-Transaction (account opening) + Periodic batch review", "control_level": "System", "evidence_generated": "System rejection logs for incomplete onboarding attempts; periodic account name validation report", "key_steps": ["Core banking system validates that a verified customer name and linked national ID or passport number are present before an account record can be saved.", "Any submission missing mandatory identity fields triggers a hard system block with an error code logged.", "A monthly batch job scans existing account records for null, numeric-only, or flagged placeholder name fields.", "Anomalies identified in the batch scan are routed to Compliance for review within five business days.", "Compliance documents the outcome of each review and escalates confirmed violations to senior management."], "residual_risk_if_failed": "High"}, {"control_title": "Customer Due Diligence Completion at Onboarding", "control_objective": "Ensure every customer relationship is subject to completed CDD before or at the point of onboarding.", "control_description": "The onboarding workflow requires all mandatory CDD tasks to be marked complete in the customer management system before an account can be activated. A compliance checklist aligned with the Implementing Regulation is embedded in the workflow and signed off by the relationship manager and a compliance reviewer. Incomplete CDD cases trigger an automated hold on account activation.", "control_owner": "Compliance / All Business Units", "control_type": "Preventive", "execution_type": "Hybrid", "frequency": "Per-Transaction (each new customer onboarding)", "control_level": "Process", "evidence_generated": "Completed CDD checklist in the customer file; account activation audit trail showing CDD sign-off date", "key_steps": ["Relationship manager initiates onboarding and is presented with a mandatory CDD checklist generated from the current Implementing Regulation requirements.", "Required documentation (identity, address, purpose of relationship, source of funds) is collected and uploaded to the customer file.", "Compliance reviewer verifies completeness and quality of CDD documentation and marks the checklist as approved.", "System allows account activation only after all checklist items show a completed status.", "Completed customer file is retained in the document management system for the required retention period."], "residual_risk_if_failed": "High"}, {"control_title": "Risk-Based Customer Risk Rating and CDD Tier Assignment", "control_objective": "Ensure the level of CDD applied to each customer is proportionate to their assessed risk rating.", "control_description": "A documented customer risk rating methodology scores customers across defined risk criteria (customer type, geography, product, transaction behavior) and automatically assigns a risk tier — Low, Medium, or High. Each tier maps to a defined CDD level: Simplified, Standard, or Enhanced. The risk rating is reviewed at onboarding, at defined periodic intervals, and on a trigger basis when material changes occur in the customer relationship.", "control_owner": "Compliance", "control_type": "Detective", "execution_type": "Hybrid", "frequency": "Per-Transaction (onboarding) + Annual periodic review + Event-Driven", "control_level": "Process", "evidence_generated": "Customer risk rating record with scoring rationale; CDD tier assignment log in the customer management system", "key_steps": ["At onboarding, the system calculates an initial risk score based on structured customer profile data using the approved scoring methodology.", "The risk score maps to a CDD tier (Simplified / Standard / Enhanced) and the corresponding due diligence tasks are auto-populated in the workflow.", "Relationship managers complete the assigned CDD tasks; Compliance reviews and approves the rating for Medium and High-risk customers.", "Risk ratings are re-evaluated annually in batch and on a trigger basis (e.g., adverse media, sanctions alert, unusual transaction pattern).", "Changes to risk ratings are documented with the reason for change and approved by the appropriate authority level."], "residual_risk_if_failed": "High"}, {"control_title": "Enhanced Due Diligence for High-Risk Customers", "control_objective": "Ensure all customers classified as high-risk are subject to documented EDD procedures including senior management approval.", "control_description": "When a customer receives a High risk rating, the system automatically triggers an EDD workflow requiring additional information collection (e.g., senior management approval, enhanced source of funds verification, more frequent periodic reviews). EDD cannot be bypassed; the account remains restricted until all EDD steps are completed and approved by an authorized compliance officer at the required seniority level.", "control_owner": "Compliance / Financial Intelligence Unit", "control_type": "Preventive", "execution_type": "Hybrid", "frequency": "Event-Driven (on High-risk rating) + Enhanced periodic review cycle", "control_level": "Process", "evidence_generated": "EDD checklist with completed fields; senior management approval record; enhanced periodic review reports", "key_steps": ["System detects High risk rating and automatically activates the EDD workflow, restricting full account access until completion.", "Relationship manager collects enhanced documentation: source of wealth, source of funds, detailed business purpose, UBO chain.", "Compliance officer at the required seniority level reviews the EDD package and either approves, requests further information, or escalates.", "Approved EDD is documented in the customer file with the approver''s identity and date.", "High-risk customers are scheduled for enhanced periodic review at a more frequent interval than standard customers (e.g., every 6 months vs. annually)."], "residual_risk_if_failed": "High"}, {"control_title": "PEP Screening and Additional Measures Workflow", "control_objective": "Ensure all customers and beneficial owners are screened against PEP databases at onboarding and on an ongoing basis, with additional measures applied upon a confirmed match.", "control_description": "The compliance screening system performs automated PEP screening for all customers and beneficial owners at onboarding and on a continuous or periodic basis thereafter using a licensed third-party database covering domestic and foreign PEPs and senior officials of international organizations. Positive matches generate alerts routed to the Financial Intelligence Unit for review. Confirmed PEP status triggers a mandatory additional measures workflow aligned with the Implementing Regulation.", "control_owner": "Compliance / Financial Intelligence Unit", "control_type": "Detective", "execution_type": "Automated", "frequency": "Per-Transaction (onboarding) + Ongoing/Daily batch rescreening", "control_level": "System", "evidence_generated": "Screening system alert log; PEP match review and disposition records; additional measures completion records in the customer file", "key_steps": ["Screening system automatically runs PEP checks on all customers and beneficial owners at onboarding using integrated third-party PEP database.", "Daily batch rescreening runs against the full customer base to catch newly designated PEPs or changes in PEP status.", "Generated alerts are routed to the FIU queue with a defined SLA for initial review (e.g., within 2 business days).", "FIU analyst reviews the alert, confirms or dismisses the match, and documents the rationale.", "Confirmed PEP matches trigger the mandatory additional measures workflow: senior management approval, enhanced source of wealth verification, and more frequent periodic reviews, all documented in the customer file."], "residual_risk_if_failed": "High"}]}'
