-- REQ-003: Correspondent Banking
UPDATE compliance_analysis
SET    stage3_json   = N'{"requirement_id": "REQ-003", "requirement_title": "Correspondent Banking", "obligations": [{"obligation_id": "REQ-003-OB-001", "obligation_text": "Before entering into a cross-border correspondent relationship, apply appropriate risk mitigation measures as prescribed by the Implementing Regulation, and satisfy themselves that the respondent institution does not permit their account to be used by a shell bank.", "execution_category": "One_Time_Implementation", "control": null}, {"obligation_id": "REQ-003-OB-002", "obligation_text": "Shall not enter into or continue a correspondent relationship with a shell bank or a respondent institution that permits its account to be used by a shell bank.", "execution_category": "Ongoing_Control", "control": {"control_title": "Correspondent Banking Shell Bank Prohibition and Periodic Review", "control_objective": "Prevent and detect any correspondent banking relationship with a shell bank or an institution that permits shell bank access.", "control_description": "The correspondent banking policy explicitly prohibits relationships with shell banks. All existing correspondent relationships are subject to periodic due diligence review that includes a reassessment of the respondent''s shell bank status. A written representation or certification from each respondent confirming no shell bank access is obtained at onboarding and refreshed at each periodic review. Any relationship where shell bank access cannot be ruled out is escalated for termination.", "control_owner": "Correspondent Banking / Compliance", "control_type": "Preventive", "execution_type": "Manual", "frequency": "Annual periodic review + Event-Driven (material changes at respondent)", "control_level": "Process", "evidence_generated": "Signed shell bank representation letter from respondent; periodic review report with shell bank assessment outcome", "key_steps": ["Correspondent banking policy is reviewed annually to confirm it contains an explicit shell bank prohibition.", "Annual due diligence review schedule is maintained for all active correspondent relationships.", "During each review, relationship manager obtains an updated written certification from the respondent confirming no shell bank access.", "Compliance reviews the certification and any supporting documentation; escalates to senior management if assurance cannot be obtained.", "Relationships where shell bank access is confirmed or cannot be ruled out are flagged for termination and reported to the MLRO."], "residual_risk_if_failed": "High"}}]}',
       analysis_json = N'{"requirement_id": "REQ-003", "requirement_title": "Correspondent Banking", "obligations": [{"obligation_id": "REQ-003-OB-001", "obligation_text": "Before entering into a cross-border correspondent relationship, apply appropriate risk mitigation measures as prescribed by the Implementing Regulation, and satisfy themselves that the respondent institution does not permit their account to be used by a shell bank.", "obligation_type": "Governance", "criticality": "High", "execution_category": "One_Time_Implementation", "evidence_expected": ["Policy", "Procedure", "Record", "Contract"], "test_method": "Auditor selects a sample of new correspondent relationships established in the review period and confirms documented due diligence and a written shell bank assurance from the respondent exist prior to relationship commencement.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 9(1)"}, {"obligation_id": "REQ-003-OB-002", "obligation_text": "Shall not enter into or continue a correspondent relationship with a shell bank or a respondent institution that permits its account to be used by a shell bank.", "obligation_type": "Preventive", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["Policy", "Record", "Log"], "test_method": "Auditor reviews the correspondent banking policy for an explicit shell bank prohibition and confirms periodic reviews of respondent banks are conducted and documented.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 9(2)"}], "controls": [{"control_title": "Correspondent Banking Shell Bank Prohibition and Periodic Review", "control_objective": "Prevent and detect any correspondent banking relationship with a shell bank or an institution that permits shell bank access.", "control_description": "The correspondent banking policy explicitly prohibits relationships with shell banks. All existing correspondent relationships are subject to periodic due diligence review that includes a reassessment of the respondent''s shell bank status. A written representation or certification from each respondent confirming no shell bank access is obtained at onboarding and refreshed at each periodic review. Any relationship where shell bank access cannot be ruled out is escalated for termination.", "control_owner": "Correspondent Banking / Compliance", "control_type": "Preventive", "execution_type": "Manual", "frequency": "Annual periodic review + Event-Driven (material changes at respondent)", "control_level": "Process", "evidence_generated": "Signed shell bank representation letter from respondent; periodic review report with shell bank assessment outcome", "key_steps": ["Correspondent banking policy is reviewed annually to confirm it contains an explicit shell bank prohibition.", "Annual due diligence review schedule is maintained for all active correspondent relationships.", "During each review, relationship manager obtains an updated written certification from the respondent confirming no shell bank access.", "Compliance reviews the certification and any supporting documentation; escalates to senior management if assurance cannot be obtained.", "Relationships where shell bank access is confirmed or cannot be ruled out are flagged for termination and reported to the MLRO."], "residual_risk_if_failed": "High"}]}'
WHERE  regulation_id  = 27880
  AND  requirement_id = 'REQ-003'
  AND  schema_version = 'v2'
  AND  is_current     = 1;

-- REQ-004: Wire Transfers
UPDATE compliance_analysis
SET    stage3_json   = N'{"requirement_id": "REQ-004", "requirement_title": "Wire Transfers", "obligations": [{"obligation_id": "REQ-004-OB-001", "obligation_text": "Financial institutions providing wire transfer activities shall obtain information on the originator and beneficiary and ensure that such information is kept with the wire transfer or related message throughout the payment chain.", "execution_category": "Ongoing_Control", "control": {"control_title": "Wire Transfer Originator and Beneficiary Data Completeness", "control_objective": "Ensure all outgoing wire transfers carry complete and accurate originator and beneficiary information throughout the payment chain.", "control_description": "The payments processing system enforces mandatory population of defined originator and beneficiary fields on all outgoing wire transfer messages before transmission. Field-level validation rules prevent submission of transfers with missing or malformed data. A post-processing reconciliation report is generated daily to confirm that all transmitted messages contained the required data fields.", "control_owner": "Operations / Payments", "control_type": "Preventive", "execution_type": "Automated", "frequency": "Per-Transaction", "control_level": "System", "evidence_generated": "Payment system validation logs; daily reconciliation report confirming originator/beneficiary field completeness", "key_steps": ["Payments system applies pre-submission validation rules checking for mandatory originator fields (name, account number, address or national ID) and beneficiary fields (name, account number, institution).", "Any transfer message failing validation is rejected with an error code and routed to the payments operations queue for resolution.", "Resolved transfers are resubmitted and re-validated before transmission.", "A daily report is generated listing all transmitted wire transfers with a completeness status; exceptions are reviewed by the payments compliance team.", "Report is archived as evidence and reviewed by Compliance on a sample basis monthly."], "residual_risk_if_failed": "High"}}, {"obligation_id": "REQ-004-OB-002", "obligation_text": "A financial institution that is unable to obtain required originator or beneficiary information shall not permit the execution of the wire transfer.", "execution_category": "Ongoing_Control", "control": {"control_title": "Wire Transfer Hard Block on Missing Mandatory Data", "control_objective": "Ensure no wire transfer is executed when required originator or beneficiary information cannot be obtained.", "control_description": "The payments system enforces a hard block rule that prevents final execution of any wire transfer where mandatory originator or beneficiary fields remain unpopulated after the validation stage. The block cannot be overridden by operations staff without documented Compliance approval. Blocked transfers are logged with the reason code and reviewed by the payments compliance team for further action including potential suspicious transaction reporting.", "control_owner": "Operations / Compliance", "control_type": "Preventive", "execution_type": "Automated", "frequency": "Per-Transaction", "control_level": "System", "evidence_generated": "System rejection log with timestamp, transfer reference, and missing field details; override approval records (if any)", "key_steps": ["Payments system applies a final pre-execution check confirming all mandatory originator and beneficiary fields are populated.", "Transfers failing this check are placed in a blocked status and cannot proceed to settlement.", "Payments operations team receives notification of the blocked transfer and contacts the initiating party to obtain missing information.", "If information cannot be obtained within the defined SLA, the transfer is formally rejected and the rejection is documented.", "Compliance reviews the rejection log weekly; patterns of recurring missing information are escalated for potential STR consideration."], "residual_risk_if_failed": "High"}}, {"obligation_id": "REQ-004-OB-003", "obligation_text": "Record all originator and beneficiary information and keep the records, documents, data, and files in accordance with Article 12.", "execution_category": "One_Time_Implementation", "control": null}, {"obligation_id": "REQ-004-OB-004", "obligation_text": "Comply with all measures on wire transfers as set out in the Implementing Regulation.", "execution_category": "Ongoing_Control", "control": {"control_title": "Wire Transfer Regulatory Compliance Gap Analysis", "control_objective": "Ensure the institution''s wire transfer policies and procedures remain fully aligned with the current Implementing Regulation.", "control_description": "Compliance maintains a living gap analysis document mapping the institution''s wire transfer policies and system controls to every specific requirement in the Implementing Regulation. The gap analysis is reviewed and updated whenever the Implementing Regulation is amended and at least annually. Any gaps identified are tracked as remediation items with owners and target completion dates.", "control_owner": "Compliance / Operations", "control_type": "Detective", "execution_type": "Manual", "frequency": "Annual + Event-Driven (regulatory update)", "control_level": "Policy", "evidence_generated": "Signed gap analysis report; remediation tracker with open and closed items", "key_steps": ["Compliance maintains a current copy of the Implementing Regulation wire transfer requirements in a structured control register.", "Annually, and on each regulatory update, Compliance maps each requirement to the corresponding internal policy clause and system control.", "Gaps between regulation and current practice are documented with a risk rating and assigned a remediation owner.", "Remediation items are tracked to closure with evidence of implementation.", "Completed gap analysis is approved by the MLRO and presented to the AML Committee."], "residual_risk_if_failed": "High"}}]}',
       analysis_json = N'{"requirement_id": "REQ-004", "requirement_title": "Wire Transfers", "obligations": [{"obligation_id": "REQ-004-OB-001", "obligation_text": "Financial institutions providing wire transfer activities shall obtain information on the originator and beneficiary and ensure that such information is kept with the wire transfer or related message throughout the payment chain.", "obligation_type": "Governance", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["System Configuration", "Log", "Procedure"], "test_method": "Auditor selects a sample of outgoing wire transfers and confirms all required originator and beneficiary fields are populated and transmitted with the payment message.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 10(1)"}, {"obligation_id": "REQ-004-OB-002", "obligation_text": "A financial institution that is unable to obtain required originator or beneficiary information shall not permit the execution of the wire transfer.", "obligation_type": "Preventive", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["System Configuration", "Log", "Procedure"], "test_method": "Auditor confirms a system-level block/reject rule exists for transfers with missing mandatory fields; reviews rejection logs to verify it is operating.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 10(1)"}, {"obligation_id": "REQ-004-OB-003", "obligation_text": "Record all originator and beneficiary information and keep the records, documents, data, and files in accordance with Article 12.", "obligation_type": "Documentation", "criticality": "Medium", "execution_category": "One_Time_Implementation", "evidence_expected": ["Record", "System Configuration"], "test_method": "Auditor confirms payment records include full originator and beneficiary data and are stored in compliance with the 10-year retention requirement under Article 12.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 10(2)"}, {"obligation_id": "REQ-004-OB-004", "obligation_text": "Comply with all measures on wire transfers as set out in the Implementing Regulation.", "obligation_type": "Governance", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["Policy", "Procedure"], "test_method": "Auditor performs a gap analysis between the wire transfer policy/procedures and the current Implementing Regulation requirements to confirm full alignment.", "clarity_score": 3, "needs_manual_review": true, "source_reference": "Article 10(3)"}], "controls": [{"control_title": "Wire Transfer Originator and Beneficiary Data Completeness", "control_objective": "Ensure all outgoing wire transfers carry complete and accurate originator and beneficiary information throughout the payment chain.", "control_description": "The payments processing system enforces mandatory population of defined originator and beneficiary fields on all outgoing wire transfer messages before transmission. Field-level validation rules prevent submission of transfers with missing or malformed data. A post-processing reconciliation report is generated daily to confirm that all transmitted messages contained the required data fields.", "control_owner": "Operations / Payments", "control_type": "Preventive", "execution_type": "Automated", "frequency": "Per-Transaction", "control_level": "System", "evidence_generated": "Payment system validation logs; daily reconciliation report confirming originator/beneficiary field completeness", "key_steps": ["Payments system applies pre-submission validation rules checking for mandatory originator fields (name, account number, address or national ID) and beneficiary fields (name, account number, institution).", "Any transfer message failing validation is rejected with an error code and routed to the payments operations queue for resolution.", "Resolved transfers are resubmitted and re-validated before transmission.", "A daily report is generated listing all transmitted wire transfers with a completeness status; exceptions are reviewed by the payments compliance team.", "Report is archived as evidence and reviewed by Compliance on a sample basis monthly."], "residual_risk_if_failed": "High"}, {"control_title": "Wire Transfer Hard Block on Missing Mandatory Data", "control_objective": "Ensure no wire transfer is executed when required originator or beneficiary information cannot be obtained.", "control_description": "The payments system enforces a hard block rule that prevents final execution of any wire transfer where mandatory originator or beneficiary fields remain unpopulated after the validation stage. The block cannot be overridden by operations staff without documented Compliance approval. Blocked transfers are logged with the reason code and reviewed by the payments compliance team for further action including potential suspicious transaction reporting.", "control_owner": "Operations / Compliance", "control_type": "Preventive", "execution_type": "Automated", "frequency": "Per-Transaction", "control_level": "System", "evidence_generated": "System rejection log with timestamp, transfer reference, and missing field details; override approval records (if any)", "key_steps": ["Payments system applies a final pre-execution check confirming all mandatory originator and beneficiary fields are populated.", "Transfers failing this check are placed in a blocked status and cannot proceed to settlement.", "Payments operations team receives notification of the blocked transfer and contacts the initiating party to obtain missing information.", "If information cannot be obtained within the defined SLA, the transfer is formally rejected and the rejection is documented.", "Compliance reviews the rejection log weekly; patterns of recurring missing information are escalated for potential STR consideration."], "residual_risk_if_failed": "High"}, {"control_title": "Wire Transfer Regulatory Compliance Gap Analysis", "control_objective": "Ensure the institution''s wire transfer policies and procedures remain fully aligned with the current Implementing Regulation.", "control_description": "Compliance maintains a living gap analysis document mapping the institution''s wire transfer policies and system controls to every specific requirement in the Implementing Regulation. The gap analysis is reviewed and updated whenever the Implementing Regulation is amended and at least annually. Any gaps identified are tracked as remediation items with owners and target completion dates.", "control_owner": "Compliance / Operations", "control_type": "Detective", "execution_type": "Manual", "frequency": "Annual + Event-Driven (regulatory update)", "control_level": "Policy", "evidence_generated": "Signed gap analysis report; remediation tracker with open and closed items", "key_steps": ["Compliance maintains a current copy of the Implementing Regulation wire transfer requirements in a structured control register.", "Annually, and on each regulatory update, Compliance maps each requirement to the corresponding internal policy clause and system control.", "Gaps between regulation and current practice are documented with a risk rating and assigned a remediation owner.", "Remediation items are tracked to closure with evidence of implementation.", "Completed gap analysis is approved by the MLRO and presented to the AML Committee."], "residual_risk_if_failed": "High"}]}'
WHERE  regulation_id  = 27880
  AND  requirement_id = 'REQ-004'
  AND  schema_version = 'v2'
  AND  is_current     = 1;

-- REQ-005: High-Risk Countries
UPDATE compliance_analysis
SET    stage3_json   = N'{"requirement_id": "REQ-005", "requirement_title": "High-Risk Countries", "obligations": [{"obligation_id": "REQ-005-OB-001", "obligation_text": "Apply enhanced due diligence measures proportionate to the risks involving business relationships and transactions with a person from a country identified as high risk by the FI or the Anti-Money Laundering Permanent Committee.", "execution_category": "Ongoing_Control", "control": {"control_title": "High-Risk Country EDD Application", "control_objective": "Ensure all customers and transactions with a nexus to a high-risk country are subject to documented enhanced due diligence.", "control_description": "Compliance maintains an approved high-risk country list incorporating designations from the AML Permanent Committee and the institution''s own country risk methodology. The customer onboarding system and transaction monitoring platform use this list to automatically flag customers and transactions with a high-risk country nexus, triggering mandatory EDD workflows or enhanced monitoring rules. The country list is reviewed quarterly and on an ad-hoc basis following official committee publications.", "control_owner": "Compliance / All Business Units", "control_type": "Preventive", "execution_type": "Hybrid", "frequency": "Per-Transaction (onboarding/transaction) + Quarterly country list review", "control_level": "Process", "evidence_generated": "Approved high-risk country list with version history; EDD completion records for flagged customers; transaction screening alert disposition logs", "key_steps": ["Compliance maintains and version-controls the approved high-risk country list, updating it within 5 business days of any official AML Permanent Committee designation.", "Onboarding system automatically checks customer nationality, residence, and UBO country of origin against the high-risk country list.", "Positive matches trigger the EDD workflow; account activation is blocked until EDD is completed and approved.", "Transaction monitoring rules apply enhanced scrutiny (lower thresholds, additional scenario coverage) to transactions involving high-risk country counterparties.", "Compliance reviews and signs off on EDD completion for all high-risk country relationships; records are retained in the customer file."], "residual_risk_if_failed": "High"}}, {"obligation_id": "REQ-005-OB-002", "obligation_text": "Apply the countermeasures prescribed by the Anti-Money Laundering Permanent Committee with respect to high risk countries.", "execution_category": "Ongoing_Control", "control": {"control_title": "AML Permanent Committee Countermeasure Implementation", "control_objective": "Ensure all countermeasures prescribed by the AML Permanent Committee for high-risk countries are implemented within the required timeframe.", "control_description": "Compliance maintains a designated mechanism for receiving and tracking official AML Permanent Committee directives. Upon receipt of a new countermeasure directive, a structured implementation project is initiated with a defined timeline, owner, and evidence requirements. System-level controls (e.g., transaction blocks, enhanced monitoring rules, restrictions on account types) are implemented by the required deadline and tested before go-live.", "control_owner": "Compliance / Sanctions Unit", "control_type": "Preventive", "execution_type": "Hybrid", "frequency": "Event-Driven (on Committee directive publication)", "control_level": "Process", "evidence_generated": "Countermeasure implementation tracker; system change records; testing evidence; sign-off from Compliance and IT", "key_steps": ["Compliance subscribes to official AML Permanent Committee publication channels and logs all incoming directives upon receipt.", "Each directive is assessed for scope and impact; an implementation plan is created with a named owner and deadline aligned to the required effective date.", "Required system or process changes are developed and tested in a non-production environment before deployment.", "Changes are deployed before the required effective date; Compliance certifies implementation in the countermeasure tracker.", "Post-implementation review is conducted within 30 days to confirm controls are operating as intended."], "residual_risk_if_failed": "High"}}]}',
       analysis_json = N'{"requirement_id": "REQ-005", "requirement_title": "High-Risk Countries", "obligations": [{"obligation_id": "REQ-005-OB-001", "obligation_text": "Apply enhanced due diligence measures proportionate to the risks involving business relationships and transactions with a person from a country identified as high risk by the FI or the Anti-Money Laundering Permanent Committee.", "obligation_type": "Governance", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["Policy", "Procedure", "Record", "Approval"], "test_method": "Auditor reviews the country risk list and selects a sample of customers from high-risk countries to confirm EDD was applied and documented.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 11(1)"}, {"obligation_id": "REQ-005-OB-002", "obligation_text": "Apply the countermeasures prescribed by the Anti-Money Laundering Permanent Committee with respect to high risk countries.", "obligation_type": "Governance", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["Policy", "Procedure", "Record"], "test_method": "Auditor reviews the mechanism for receiving Committee directives and confirms countermeasures are implemented within the required timeframe after official publication.", "clarity_score": 4, "needs_manual_review": false, "source_reference": "Article 11(2)"}], "controls": [{"control_title": "High-Risk Country EDD Application", "control_objective": "Ensure all customers and transactions with a nexus to a high-risk country are subject to documented enhanced due diligence.", "control_description": "Compliance maintains an approved high-risk country list incorporating designations from the AML Permanent Committee and the institution''s own country risk methodology. The customer onboarding system and transaction monitoring platform use this list to automatically flag customers and transactions with a high-risk country nexus, triggering mandatory EDD workflows or enhanced monitoring rules. The country list is reviewed quarterly and on an ad-hoc basis following official committee publications.", "control_owner": "Compliance / All Business Units", "control_type": "Preventive", "execution_type": "Hybrid", "frequency": "Per-Transaction (onboarding/transaction) + Quarterly country list review", "control_level": "Process", "evidence_generated": "Approved high-risk country list with version history; EDD completion records for flagged customers; transaction screening alert disposition logs", "key_steps": ["Compliance maintains and version-controls the approved high-risk country list, updating it within 5 business days of any official AML Permanent Committee designation.", "Onboarding system automatically checks customer nationality, residence, and UBO country of origin against the high-risk country list.", "Positive matches trigger the EDD workflow; account activation is blocked until EDD is completed and approved.", "Transaction monitoring rules apply enhanced scrutiny (lower thresholds, additional scenario coverage) to transactions involving high-risk country counterparties.", "Compliance reviews and signs off on EDD completion for all high-risk country relationships; records are retained in the customer file."], "residual_risk_if_failed": "High"}, {"control_title": "AML Permanent Committee Countermeasure Implementation", "control_objective": "Ensure all countermeasures prescribed by the AML Permanent Committee for high-risk countries are implemented within the required timeframe.", "control_description": "Compliance maintains a designated mechanism for receiving and tracking official AML Permanent Committee directives. Upon receipt of a new countermeasure directive, a structured implementation project is initiated with a defined timeline, owner, and evidence requirements. System-level controls (e.g., transaction blocks, enhanced monitoring rules, restrictions on account types) are implemented by the required deadline and tested before go-live.", "control_owner": "Compliance / Sanctions Unit", "control_type": "Preventive", "execution_type": "Hybrid", "frequency": "Event-Driven (on Committee directive publication)", "control_level": "Process", "evidence_generated": "Countermeasure implementation tracker; system change records; testing evidence; sign-off from Compliance and IT", "key_steps": ["Compliance subscribes to official AML Permanent Committee publication channels and logs all incoming directives upon receipt.", "Each directive is assessed for scope and impact; an implementation plan is created with a named owner and deadline aligned to the required effective date.", "Required system or process changes are developed and tested in a non-production environment before deployment.", "Changes are deployed before the required effective date; Compliance certifies implementation in the countermeasure tracker.", "Post-implementation review is conducted within 30 days to confirm controls are operating as intended."], "residual_risk_if_failed": "High"}]}'
WHERE  regulation_id  = 27880
