-- REQ-006: Record Keeping
UPDATE compliance_analysis
SET    stage3_json   = N'{"requirement_id": "REQ-006", "requirement_title": "Record Keeping", "obligations": [{"obligation_id": "REQ-006-OB-001", "obligation_text": "Keep all records and documents for domestic or international financial transactions as well as commercial and monetary transactions for a period of no less than ten years from the date of concluding the transaction or closure of account.", "execution_category": "One_Time_Implementation", "control": null}, {"obligation_id": "REQ-006-OB-002", "obligation_text": "Keep all records obtained through due diligence measures, account files and business correspondences and copies of personal identification documents, including analysis results, for at least ten years after the business relationship has ended or after an occasional transaction.", "execution_category": "One_Time_Implementation", "control": null}, {"obligation_id": "REQ-006-OB-003", "obligation_text": "Records shall be sufficient to permit reconstruction of transactions and shall be maintained in a manner so that they can be readily made available to competent authorities upon request.", "execution_category": "One_Time_Implementation", "control": null}, {"obligation_id": "REQ-006-OB-004", "obligation_text": "Keep records of examined transactions for a period of ten years and make them available to competent authorities upon request.", "execution_category": "One_Time_Implementation", "control": null}]}',
       analysis_json = N'{"requirement_id": "REQ-006", "requirement_title": "Record Keeping", "obligations": [{"obligation_id": "REQ-006-OB-001", "obligation_text": "Keep all records and documents for domestic or international financial transactions as well as commercial and monetary transactions for a period of no less than ten years from the date of concluding the transaction or closure of account.", "obligation_type": "Documentation", "criticality": "Medium", "execution_category": "One_Time_Implementation", "evidence_expected": ["Policy", "System Configuration", "Record"], "test_method": "Auditor reviews the records retention policy for a 10-year minimum requirement and samples archived transaction records to confirm they are retrievable and within retention period.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 12(1)"}, {"obligation_id": "REQ-006-OB-002", "obligation_text": "Keep all records obtained through due diligence measures, account files and business correspondences and copies of personal identification documents, including analysis results, for at least ten years after the business relationship has ended or after an occasional transaction.", "obligation_type": "Documentation", "criticality": "Medium", "execution_category": "One_Time_Implementation", "evidence_expected": ["Policy", "System Configuration", "Record"], "test_method": "Auditor samples closed customer files and confirms CDD records, ID copies, and correspondence are retained and accessible for the required 10-year post-relationship period.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 12(2)"}, {"obligation_id": "REQ-006-OB-003", "obligation_text": "Records shall be sufficient to permit reconstruction of transactions and shall be maintained in a manner so that they can be readily made available to competent authorities upon request.", "obligation_type": "Documentation", "criticality": "Medium", "execution_category": "One_Time_Implementation", "evidence_expected": ["Policy", "Record", "Procedure"], "test_method": "Auditor conducts a simulated authority request and measures the time to retrieve complete, legible transaction records; confirms data format and integrity standards are in place.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 12(4)"}, {"obligation_id": "REQ-006-OB-004", "obligation_text": "Keep records of examined transactions for a period of ten years and make them available to competent authorities upon request.", "obligation_type": "Documentation", "criticality": "Medium", "execution_category": "One_Time_Implementation", "evidence_expected": ["Policy", "Record", "System Configuration"], "test_method": "Auditor confirms transaction monitoring examination records and investigation notes are archived for a minimum of 10 years and can be retrieved upon a simulated authority request.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 13(4)"}], "controls": []}'
WHERE  regulation_id  = 27880
  AND  requirement_id = 'REQ-006'
  AND  schema_version = 'v2'
  AND  is_current     = 1;

-- REQ-007: Transaction Monitoring
UPDATE compliance_analysis
SET    stage3_json   = N'{"requirement_id": "REQ-007", "requirement_title": "Transaction Monitoring", "obligations": [{"obligation_id": "REQ-007-OB-001", "obligation_text": "Monitor and scrutinize transactions, document and data on an ongoing basis to ensure consistency with the knowledge of the customer, the customer''s commercial activities and risk profile, and where necessary the customer''s source of funds.", "execution_category": "Ongoing_Control", "control": {"control_title": "Ongoing Transaction Monitoring Against Customer Profile", "control_objective": "Detect transactions that are inconsistent with the customer''s known commercial activities, risk profile, or source of funds.", "control_description": "The transaction monitoring system operates scenario-based rules and behavioral analytics calibrated to each customer''s risk profile and expected activity patterns. Generated alerts are routed to the FIU for review within a defined SLA. Investigators document their analysis and disposition for every alert; alerts that cannot be satisfactorily explained are escalated for STR consideration.", "control_owner": "Financial Intelligence Unit / Compliance", "control_type": "Detective", "execution_type": "Automated", "frequency": "Daily (batch) + Real-Time (for defined high-risk scenarios)", "control_level": "System", "evidence_generated": "Transaction monitoring alert log; analyst review and disposition records; escalation records", "key_steps": ["Transaction monitoring system ingests daily transaction data and runs it against active detection scenarios segmented by customer risk tier.", "Generated alerts are automatically assigned to FIU analysts based on workload and complexity.", "Analyst reviews alert context including customer profile, historical transaction patterns, and declared source of funds; documents analysis in the case management system.", "Alert is either closed with a documented rationale or escalated to the MLRO for STR consideration.", "Alert disposition metrics (volume, review time, STR conversion rate) are reported to Compliance management monthly."], "residual_risk_if_failed": "High"}}, {"obligation_id": "REQ-007-OB-002", "obligation_text": "Examine any complex and unusual large transaction, and any unusual pattern of transactions that has no clear economic or legal objective.", "execution_category": "Ongoing_Control", "control": {"control_title": "Complex and Unusual Transaction Examination", "control_objective": "Ensure every complex, unusually large, or pattern-based suspicious transaction is examined and documented.", "control_description": "Transaction monitoring rules include specific scenarios targeting complex transactions (multiple legs, unusual intermediary chains), unusually large transactions (calibrated thresholds by customer type), and pattern-based anomalies (structuring, round-trip flows, velocity anomalies). Each triggered alert generates a mandatory examination record. The examination outcome is documented regardless of whether an STR is filed.", "control_owner": "Financial Intelligence Unit", "control_type": "Detective", "execution_type": "Hybrid", "frequency": "Per-Transaction (scenario-based) + Daily batch", "control_level": "System", "evidence_generated": "Case examination record with transaction details, analysis narrative, and disposition; pattern analysis reports", "key_steps": ["Transaction monitoring system applies complexity, large-value, and pattern-detection scenarios to all transaction data.", "Triggered alerts are escalated to the FIU as examination cases with a defined priority and review SLA.", "FIU analyst examines the transaction(s), reviews customer profile, requests additional information from the business if required, and documents findings.", "If a clear economic or legal explanation is established, the case is closed with a documented rationale; if not, it is escalated to the MLRO.", "All examination records, including closed cases, are retained for 10 years in the case management system."], "residual_risk_if_failed": "High"}}, {"obligation_id": "REQ-007-OB-003", "obligation_text": "Where the risks of money laundering are higher, perform enhanced due diligence and increase the level and nature of monitoring of the relevant business relationship to determine whether the transaction is unusual or suspicious.", "execution_category": "Ongoing_Control", "control": {"control_title": "Enhanced Monitoring for High-Risk Customer Relationships", "control_objective": "Apply heightened transaction monitoring parameters to all business relationships assessed as high-risk.", "control_description": "High-risk customers are assigned enhanced monitoring profiles in the transaction monitoring system, which applies lower alert thresholds, broader scenario coverage, and more frequent periodic transaction reviews compared to standard-risk customers. Compliance maintains a documented mapping of risk tiers to monitoring parameters. High-risk customer monitoring profiles are reviewed whenever the customer''s risk rating changes.", "control_owner": "Financial Intelligence Unit / Compliance", "control_type": "Detective", "execution_type": "Automated", "frequency": "Ongoing (continuous monitoring) + Periodic review (every 6 months for high-risk)", "control_level": "System", "evidence_generated": "High-risk customer monitoring profile configuration records; enhanced periodic transaction review reports; alert volume and disposition records by risk tier", "key_steps": ["Transaction monitoring system maintains a risk-tier parameter table; high-risk customers are configured with lower transaction thresholds and additional active scenarios.", "Any change in a customer''s risk rating automatically triggers a corresponding update to their monitoring profile.", "FIU conducts a scheduled enhanced periodic transaction review for each high-risk customer at least every six months, regardless of alert activity.", "Review findings are documented and any unusual activity identified during the periodic review is assessed for STR consideration.", "Compliance reviews the high-risk monitoring parameter table at least annually to confirm calibration remains appropriate."], "residual_risk_if_failed": "High"}}]}',
       analysis_json = N'{"requirement_id": "REQ-007", "requirement_title": "Transaction Monitoring", "obligations": [{"obligation_id": "REQ-007-OB-001", "obligation_text": "Monitor and scrutinize transactions, document and data on an ongoing basis to ensure consistency with the knowledge of the customer, the customer''s commercial activities and risk profile, and where necessary the customer''s source of funds.", "obligation_type": "Detective", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["System Configuration", "Log", "Procedure", "Report"], "test_method": "Auditor reviews the transaction monitoring system configuration for active scenario-based rules and confirms a sample of generated alerts were reviewed and documented within the defined timeframe.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 13(1)"}, {"obligation_id": "REQ-007-OB-002", "obligation_text": "Examine any complex and unusual large transaction, and any unusual pattern of transactions that has no clear economic or legal objective.", "obligation_type": "Detective", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["Procedure", "Log", "Record"], "test_method": "Auditor reviews the thresholds and detection scenarios for complex/unusual transactions and confirms a sample of flagged transactions have documented examination outcomes.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 13(2)"}, {"obligation_id": "REQ-007-OB-003", "obligation_text": "Where the risks of money laundering are higher, perform enhanced due diligence and increase the level and nature of monitoring of the relevant business relationship to determine whether the transaction is unusual or suspicious.", "obligation_type": "Detective", "criticality": "High", "execution_category": "Ongoing_Control", "evidence_expected": ["Procedure", "Record", "Log"], "test_method": "Auditor selects a sample of high-risk customers and confirms enhanced monitoring parameters (lower thresholds, higher frequency reviews) are applied and documented.", "clarity_score": 5, "needs_manual_review": false, "source_reference": "Article 13(3)"}], "controls": [{"control_title": "Ongoing Transaction Monitoring Against Customer Profile", "control_objective": "Detect transactions that are inconsistent with the customer''s known commercial activities, risk profile, or source of funds.", "control_description": "The transaction monitoring system operates scenario-based rules and behavioral analytics calibrated to each customer''s risk profile and expected activity patterns. Generated alerts are routed to the FIU for review within a defined SLA. Investigators document their analysis and disposition for every alert; alerts that cannot be satisfactorily explained are escalated for STR consideration.", "control_owner": "Financial Intelligence Unit / Compliance", "control_type": "Detective", "execution_type": "Automated", "frequency": "Daily (batch) + Real-Time (for defined high-risk scenarios)", "control_level": "System", "evidence_generated": "Transaction monitoring alert log; analyst review and disposition records; escalation records", "key_steps": ["Transaction monitoring system ingests daily transaction data and runs it against active detection scenarios segmented by customer risk tier.", "Generated alerts are automatically assigned to FIU analysts based on workload and complexity.", "Analyst reviews alert context including customer profile, historical transaction patterns, and declared source of funds; documents analysis in the case management system.", "Alert is either closed with a documented rationale or escalated to the MLRO for STR consideration.", "Alert disposition metrics (volume, review time, STR conversion rate) are reported to Compliance management monthly."], "residual_risk_if_failed": "High"}, {"control_title": "Complex and Unusual Transaction Examination", "control_objective": "Ensure every complex, unusually large, or pattern-based suspicious transaction is examined and documented.", "control_description": "Transaction monitoring rules include specific scenarios targeting complex transactions (multiple legs, unusual intermediary chains), unusually large transactions (calibrated thresholds by customer type), and pattern-based anomalies (structuring, round-trip flows, velocity anomalies). Each triggered alert generates a mandatory examination record. The examination outcome is documented regardless of whether an STR is filed.", "control_owner": "Financial Intelligence Unit", "control_type": "Detective", "execution_type": "Hybrid", "frequency": "Per-Transaction (scenario-based) + Daily batch", "control_level": "System", "evidence_generated": "Case examination record with transaction details, analysis narrative, and disposition; pattern analysis reports", "key_steps": ["Transaction monitoring system applies complexity, large-value, and pattern-detection scenarios to all transaction data.", "Triggered alerts are escalated to the FIU as examination cases with a defined priority and review SLA.", "FIU analyst examines the transaction(s), reviews customer profile, requests additional information from the business if required, and documents findings.", "If a clear economic or legal explanation is established, the case is closed with a documented rationale; if not, it is escalated to the MLRO.", "All examination records, including closed cases, are retained for 10 years in the case management system."], "residual_risk_if_failed": "High"}, {"control_title": "Enhanced Monitoring for High-Risk Customer Relationships", "control_objective": "Apply heightened transaction monitoring parameters to all business relationships assessed as high-risk.", "control_description": "High-risk customers are assigned enhanced monitoring profiles in the transaction monitoring system, which applies lower alert thresholds, broader scenario coverage, and more frequent periodic transaction reviews compared to standard-risk customers. Compliance maintains a documented mapping of risk tiers to monitoring parameters. High-risk customer monitoring profiles are reviewed whenever the customer''s risk rating changes.", "control_owner": "Financial Intelligence Unit / Compliance", "control_type": "Detective", "execution_type": "Automated", "frequency": "Ongoing (continuous monitoring) + Periodic review (every 6 months for high-risk)", "control_level": "System", "evidence_generated": "High-risk customer monitoring profile configuration records; enhanced periodic transaction review reports; alert volume and disposition records by risk tier", "key_steps": ["Transaction monitoring system maintains a risk-tier parameter table; high-risk customers are configured with lower transaction thresholds and additional active scenarios.", "Any change in a customer''s risk rating automatically triggers a corresponding update to their monitoring profile.", "FIU conducts a scheduled enhanced periodic transaction review for each high-risk customer at least every six months, regardless of alert activity.", "Review findings are documented and any unusual activity identified during the periodic review is assessed for STR consideration.", "Compliance reviews the high-risk monitoring parameter table at least annually to confirm calibration remains appropriate."], "residual_risk_if_failed": "High"}]}'
WHERE  regulation_id  = 27880
  AND  requirement_id = 'REQ-007'
  AND  schema_version = 'v2'
  AND  is_current     = 1;

