UPDATE compliance_analysis
SET    stage3_json   = N'{"requirement_id": "REQ-009", "requirement_title": "STR Reporting & FIU Cooperation", "obligations": [{"obligation_id": "REQ-009-OB-001", "obligation_text": "Promptly and directly report to the General Directorate of Financial Intelligence any transaction suspected or having reasonable grounds to suspect involves proceeds of crime or money laundering, including attempts. Provide a detailed report including all available data and information.", "execution_category": "One_Off_Reporting", "control": null}, {"obligation_id": "REQ-009-OB-002", "obligation_text": "Promptly and fully respond to requests from the General Directorate of Financial Intelligence for additional information.", "execution_category": "One_Time_Implementation", "control": null}, {"obligation_id": "REQ-009-OB-003", "obligation_text": "Prohibit directors, management, and employees from disclosing to a customer or any other person the fact that a report under this Law or related information will be, is being or has been submitted to the Directorate, or that a criminal investigation is being or has been carried out.", "execution_category": "Ongoing_Control", "control": {"control_title": "Tipping-Off Prohibition Enforcement and Training", "control_objective": "Ensure all staff are aware of and comply with the prohibition on disclosing STR-related information to customers or third parties.", "control_description": "The tipping-off prohibition is embedded in the employee code of conduct, the AML/CFT policy, and the STR handling procedure. All relevant staff complete mandatory annual AML training that includes a dedicated module on tipping-off obligations and consequences. The STR process enforces strict information barriers: only authorized personnel involved in the STR workflow have access to STR-related records, and all such access is logged.", "control_owner": "Compliance / Human Resources", "control_type": "Preventive", "execution_type": "Hybrid", "frequency": "Ongoing (access controls) + Annual (training)", "control_level": "Process", "evidence_generated": "Annual AML training completion records by staff member; AML policy and code of conduct with tipping-off clause; STR system access log", "key_steps": ["AML policy and employee code of conduct are reviewed annually to confirm the tipping-off prohibition is explicitly and clearly stated.", "Annual AML training program includes a mandatory tipping-off module; completion is tracked in the HR learning management system.", "STR case management system restricts access to STR records to authorized FIU and Compliance personnel only; access is logged and reviewed quarterly.", "Any suspected tipping-off incident is reported to the MLRO and escalated for investigation; outcomes are documented.", "Compliance reports annual training completion rates to senior management; staff with overdue training are escalated through line management."], "residual_risk_if_failed": "High"}}, {"obligation_id": "REQ-009-OB-004", "obligation_text": "Provide any additional information requested by the General Directorate of Financial Intelligence promptly, including through the supervisory authority when the request does not relate to a submitted report.", "execution_category": "One_Time_Implementation", "control": null}]}',
